import { type TeamHuntState } from "@hunt/public-client";
import {
  CutsceneOverlay,
  LOCAL_STORAGE_CUTSCENE_VIEWED_KEY,
} from "@hunt/puzzle-components";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { type ResolvedCutsceneInfo, type StoryState } from "../../client/story";
import { StoryFolder } from "./StoryFolder";
import filmFrame from "./assets/film_frame.svg";
import newBookmark from "./assets/new_bookmark.svg";

type StoryBlockProps = {
  cutscene: ResolvedCutsceneInfo;
  showNewTag?: boolean;
  onClick: () => void;
};

const StoryBlock = ({ cutscene, showNewTag, onClick }: StoryBlockProps) => {
  return (
    <button
      onClick={onClick}
      className="group/story-block flex flex-col items-center justify-start w-40 gap-2 transition relative mt-3 select-none"
      aria-label={`View story: ${cutscene.title}`}
    >
      <div className="w-fit h-fit relative group-hover/story-block:translate-y-[-12px] transition">
        <img
          src={filmFrame}
          alt=""
          className="w-full px-2 transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)]"
        />
        {cutscene.storyBackgroundImage || cutscene.backgroundImage ? (
          <img
            src={cutscene.storyBackgroundImage || cutscene.backgroundImage}
            alt=""
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[59%] h-[92%] object-cover blur-xs"
          />
        ) : (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[59%] h-[92%] bg-gradient-to-b from-[#4788E9] to-[#153A62]" />
        )}
        <div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)]"
          style={{
            borderTop: "14px solid transparent",
            borderBottom: "14px solid transparent",
            borderLeft: "24px solid white",
          }}
        />
      </div>
      <span className="text-lg text-black text-center leading-6">
        {cutscene.title}
      </span>
      {showNewTag && (
        <div className="absolute -top-2 -right-2 w-[43%] select-none">
          <img
            src={newBookmark}
            alt=""
            aria-hidden="true"
            className="pointer-events-none h-full w-full object-contain transform-gpu drop-shadow-[-1px_2px_2px_rgba(0,0,0,0.45)]"
          />
          <span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pr-1.5 font-semibold italic text-accent-green whitespace-nowrap text-sm lg:text-base">
            NEW
          </span>
        </div>
      )}
    </button>
  );
};

export const StoryPage = ({
  state,
  teamState,
}: {
  state: StoryState;
  teamState: TeamHuntState;
}) => {
  const [playingCutscene, setPlayingCutscene] =
    useState<ResolvedCutsceneInfo | null>(null);

  // Avoid SSR/first-paint flicker: don't show the component until we've hydrated
  // and merged any locally stored viewed state.
  const [hasHydrated, setHasHydrated] = useState(false);

  // Track viewed cutscenes locally for immediate UI updates
  const [viewedCutscenes, setViewedCutscenes] = useState<Set<string>>(
    () => new Set(state.cutscenes.viewed),
  );

  // Group cutscenes by category from server-provided list
  const {
    dimensionCutscenes,
    introCutscenes,
    connectTheClansCutscenes,
    artifactCutscenes,
  } = useMemo(() => {
    const dimensionCutscenes: Record<string, ResolvedCutsceneInfo[]> = {};
    const introCutscenes: ResolvedCutsceneInfo[] = [];
    const connectTheClansCutscenes: ResolvedCutsceneInfo[] = [];
    const artifactCutscenes: ResolvedCutsceneInfo[] = [];

    for (const cutscene of state.cutscenes.list) {
      if (cutscene.category === "link") {
        introCutscenes.push(cutscene);
      } else if (cutscene.category === "overlay" && cutscene.roundSlug) {
        // Separate Kingdom of the Puzzmon cutscenes from dimension rounds
        const isConnectTheClans =
          cutscene.id === "kc01" || cutscene.id === "kc02";
        const isArtifact = cutscene.id === "kc03" || cutscene.id === "kc04";

        if (isConnectTheClans) {
          connectTheClansCutscenes.push(cutscene);
        } else if (isArtifact) {
          artifactCutscenes.push(cutscene);
        } else {
          if (!dimensionCutscenes[cutscene.roundSlug]) {
            dimensionCutscenes[cutscene.roundSlug] = [];
          }
          dimensionCutscenes[cutscene.roundSlug].push(cutscene);
        }
      }
    }

    return {
      dimensionCutscenes,
      introCutscenes,
      connectTheClansCutscenes,
      artifactCutscenes,
    };
  }, [state.cutscenes.list]);

  // Helper function to get folder name for a cutscene
  const getFolderName = useCallback(
    (cutscene: ResolvedCutsceneInfo): string => {
      const folderTitle = cutscene.folderTitle as string | undefined;
      if (folderTitle) {
        return folderTitle;
      }
      if (cutscene.roundSlug) {
        const round = teamState.rounds[cutscene.roundSlug];
        const roundTitle = round?.title as string | undefined;
        return roundTitle ?? cutscene.roundSlug;
      }
      return cutscene.id;
    },
    [teamState.rounds],
  );

  const handleCutsceneClick = useCallback(
    (cutscene: ResolvedCutsceneInfo) => {
      if (cutscene.category === "overlay") {
        setPlayingCutscene(cutscene);
        // Update URL with cutscene query parameter
        // Format: folderName_title (e.g., "Connect the Clans_Intro" or "terminus_Intro")
        const urlParams = new URLSearchParams(window.location.search);
        const folderName = getFolderName(cutscene);
        const cutsceneParam = cutscene.title
          ? `${folderName.toLowerCase().replaceAll(" ", "_")}_${cutscene.title.toLowerCase().replaceAll(" ", "_")}`
          : cutscene.id;
        urlParams.set("cutscene", cutsceneParam);
        const newUrl = window.location.pathname + `?${urlParams.toString()}`;
        window.history.replaceState({}, "", newUrl);
      } else {
        window.location.assign(cutscene.link);
      }
    },
    [getFolderName],
  );

  const handleCutsceneClose = useCallback(() => {
    if (playingCutscene) {
      // Mark as viewed when closed
      setViewedCutscenes((prev) => {
        const updated = new Set(prev);
        if (!updated.has(playingCutscene.id)) {
          updated.add(playingCutscene.id);
          // Store viewed state in localStorage for persistence
          // This will be synced with the server later if needed
          const viewedArray = Array.from(updated);
          localStorage.setItem(
            LOCAL_STORAGE_CUTSCENE_VIEWED_KEY,
            JSON.stringify(viewedArray),
          );
        }
        return updated;
      });
    }
    setPlayingCutscene(null);

    // Remove cutscene query parameter from URL if present
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.has("cutscene")) {
      urlParams.delete("cutscene");
      const newUrl =
        window.location.pathname +
        (urlParams.toString() ? `?${urlParams.toString()}` : "");
      window.history.replaceState({}, "", newUrl);
    }
  }, [playingCutscene]);

  // Load viewed state from localStorage on mount and merge with server state
  useEffect(() => {
    try {
      const stored = localStorage.getItem(LOCAL_STORAGE_CUTSCENE_VIEWED_KEY);
      if (stored) {
        const viewed = JSON.parse(stored) as string[];
        // Merge with server state
        const mergedViewed = new Set([...state.cutscenes.viewed, ...viewed]);
        setViewedCutscenes(mergedViewed);
      }
    } catch {
      // Ignore localStorage errors
    }
    setHasHydrated(true);
  }, [state.cutscenes.viewed]);

  // Check for cutscene query parameter on mount
  useEffect(() => {
    if (!hasHydrated) {
      return;
    }

    const urlParams = new URLSearchParams(window.location.search);
    const cutsceneParam = urlParams.get("cutscene");

    if (cutsceneParam) {
      let cutscene: ResolvedCutsceneInfo | undefined;

      // Try to parse as folderName_title format
      const underscoreIndex = cutsceneParam.lastIndexOf("_");
      if (underscoreIndex > 0) {
        const folderNameParam = cutsceneParam.slice(0, underscoreIndex);
        const normalizedTitle = cutsceneParam.slice(underscoreIndex + 1);

        // Find cutscene by matching folder name and title
        cutscene = state.cutscenes.list.find((c) => {
          if (c.category !== "overlay" || !c.title) {
            return false;
          }
          const cutsceneTitle = c.title.toLowerCase().replaceAll(" ", "_");
          let folderName: string;
          const folderTitle = c.folderTitle as string | undefined;
          if (folderTitle) {
            folderName = folderTitle.toLowerCase().replaceAll(" ", "_");
          } else if (c.roundSlug) {
            const round = teamState.rounds[c.roundSlug];
            const roundTitle = round?.title as string | undefined;
            folderName = roundTitle
              ? roundTitle.toLowerCase().replaceAll(" ", "_")
              : c.roundSlug;
          } else {
            folderName = c.id;
          }
          return (
            folderName === folderNameParam && cutsceneTitle === normalizedTitle
          );
        });
      }

      // If still not found, try by cutscene ID
      if (!cutscene) {
        cutscene = state.cutscenes.list.find(
          (c) => c.id === cutsceneParam && c.category === "overlay",
        );
      }

      if (cutscene) {
        setPlayingCutscene(cutscene);
      }
    }
  }, [hasHydrated, state.cutscenes.list, teamState.rounds]);

  return hasHydrated ? (
    <>
      <div className="flex flex-wrap gap-6 justify-center min-w-[356px]">
        {/* Introduction cutscenes */}
        {introCutscenes.length > 0 && (
          <StoryFolder title="Introduction" className="w-[356px]">
            {introCutscenes.map((cutscene) => {
              return (
                <StoryBlock
                  key={cutscene.id}
                  cutscene={cutscene}
                  onClick={() => {
                    handleCutsceneClick(cutscene);
                  }}
                />
              );
            })}
          </StoryFolder>
        )}

        {/* Artifact cutscenes */}
        {artifactCutscenes.length > 0 &&
          teamState.rounds.kingdom_of_the_puzzmon?.locked === "unlocked" && (
            <StoryFolder
              title={
                (artifactCutscenes[0]?.folderTitle as string | undefined) ??
                (teamState.rounds.kingdom_of_the_puzzmon?.title as
                  | string
                  | undefined) ??
                "kingdom_of_the_puzzmon"
              }
              className="w-[356px]"
            >
              {artifactCutscenes.map((cutscene) => {
                return (
                  <StoryBlock
                    key={cutscene.id}
                    cutscene={cutscene}
                    showNewTag={!viewedCutscenes.has(cutscene.id)}
                    onClick={() => {
                      handleCutsceneClick(cutscene);
                    }}
                  />
                );
              })}
            </StoryFolder>
          )}

        {/* Connect the Clans cutscenes */}
        {connectTheClansCutscenes.length > 0 &&
          teamState.rounds.kingdom_of_the_puzzmon?.locked === "unlocked" && (
            <StoryFolder
              title={
                (connectTheClansCutscenes[0]?.folderTitle as
                  | string
                  | undefined) ??
                (teamState.rounds.kingdom_of_the_puzzmon?.title as
                  | string
                  | undefined) ??
                "kingdom_of_the_puzzmon"
              }
              className="w-[356px]"
            >
              {connectTheClansCutscenes.map((cutscene) => {
                return (
                  <StoryBlock
                    key={cutscene.id}
                    cutscene={cutscene}
                    showNewTag={!viewedCutscenes.has(cutscene.id)}
                    onClick={() => {
                      handleCutsceneClick(cutscene);
                    }}
                  />
                );
              })}
            </StoryFolder>
          )}

        {/* Dimension cutscenes */}
        {Object.entries(dimensionCutscenes)
          .filter(
            ([roundSlug]) => teamState.rounds[roundSlug]?.locked === "unlocked",
          )
          .map(([roundSlug, cutscenes]) => {
            // Use folderTitle from cutscene if available, otherwise use round title
            const round = teamState.rounds[roundSlug];
            const folderTitle: string =
              (cutscenes[0]?.folderTitle as string | undefined) ??
              (round?.title as string | undefined) ??
              roundSlug;
            return (
              <StoryFolder
                key={roundSlug}
                title={folderTitle}
                className="w-[356px]"
              >
                {cutscenes.map((cutscene) => {
                  return (
                    <StoryBlock
                      key={cutscene.id}
                      cutscene={cutscene}
                      showNewTag={!viewedCutscenes.has(cutscene.id)}
                      onClick={() => {
                        handleCutsceneClick(cutscene);
                      }}
                    />
                  );
                })}
              </StoryFolder>
            );
          })}
      </div>

      {/* Cutscene overlay */}
      {playingCutscene?.category === "overlay" && (
        <CutsceneOverlay
          content={playingCutscene.content}
          onClose={handleCutsceneClose}
        />
      )}
    </>
  ) : null;
};
