import { type CutsceneInfo } from "@hunt/hunt-data/cutscenes";
import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { StoryPage } from "../components/StoryPage/StoryPage";
import useDataset from "./useDataset";

export type { ResolvedCutsceneContent } from "@hunt/puzzle-components";

export type ResolvedCutsceneInfo = Omit<CutsceneInfo, "content"> &
  (
    | { category: "overlay"; content: ResolvedCutsceneContent }
    | { category: "link"; link: string }
  );

export type StoryState = {
  epoch: number;
  cutscenes: {
    list: ResolvedCutsceneInfo[]; // List of unlocked cutscenes from server
    viewed: string[]; // Array of cutscene IDs that have been viewed
  };
};

const StoryManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: StoryState;
  initialTeamState: TeamHuntState;
}) => {
  const state = useDataset("story", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);

  return <StoryPage state={state} teamState={teamState} />;
};

type WindowWithStoryState = {
  initialStoryState: StoryState;
  initialTeamState: TeamHuntState;
} & Window;

const storyElem = document.getElementById("story-root");
if (storyElem) {
  const windowWithState = window as unknown as WindowWithStoryState;
  const initialStoryState = windowWithState.initialStoryState;
  const teamState = windowWithState.initialTeamState;
  hydrateRoot(
    storyElem,
    <StoryManager
      initialState={initialStoryState}
      initialTeamState={teamState}
    />,
  );
} else {
  console.error(
    "Couldn't mount StoryManager because #story-root was nowhere to be found",
  );
}
